use std::path::PathBuf;

use base64::Engine;
use base64::engine::general_purpose::STANDARD;

pub(crate) fn write(
    directory: &std::path::Path,
    extension: &str,
) -> Result<PathBuf, Box<dyn std::error::Error>> {
    let encoded = match extension {
        "untagged.flac" => UNTAGGED_FLAC,
        "flac" => FLAC,
        "mp3" => MP3,
        "opus" => OPUS,
        "ogg" => OGG,
        "m4a" => M4A,
        _ => return Err(format!("unsupported fixture extension: {extension}").into()),
    };
    let path = directory.join(format!("fixture.{extension}"));
    std::fs::write(&path, STANDARD.decode(encoded)?)?;
    Ok(path)
}

const FLAC: &str = "";
const MP3: &str = "";
const OPUS: &str = "";
const OGG: &str = "";
const M4A: &str = "";

const UNTAGGED_FLAC: &str = "";
